#include "common/gpu/MaterialPublicationResolution.H"
#include <cassert>
#include <cstdio>
template<class R> struct Law { R enthalpy(R t)const{return R(1500)*t;} };
template<class R> void test(){using namespace ugkp::gpu;R t=R(2100),g=publicationTemperatureGrid(t,R(0),R(100000),Law<R>{});assert(g>0);auto zero=assessMaterialPublication(R(0),R(0),R(0),R(1e-5));assert(zero.accepted&&!zero.usedTemperatureGrid);auto near=assessMaterialPublication(R(0),g/R(10),g,R(1e-5));assert(near.accepted&&near.usedTemperatureGrid&&near.rawNormalized==R(1));auto bad=assessMaterialPublication(R(0),g*R(2),g,R(1e-5));assert(!bad.accepted);auto nan=assessMaterialPublication(R(0),std::numeric_limits<R>::quiet_NaN(),g,R(1e-5));assert(!nan.valid&&!nan.accepted);auto genuine=assessMaterialPublication(R(1),R(1)+R(1e-6),R(0),R(1e-5));assert(genuine.accepted&&!genuine.usedTemperatureGrid);printf("bits=%zu grid=%.17g nearRaw=%.17g nearEffective=%.17g rejectEffective=%.17g\n",8*sizeof(R),double(g),double(near.rawNormalized),double(near.effectiveNormalized),double(bad.effectiveNormalized));}
int main(){test<float>();test<double>();using namespace ugkp::gpu;auto c=assessMaterialPublication(-2.79849973594537e-6f,-2.7986034183413722e-6f,6.25e-9f,3.814697265625e-6f);assert(c.accepted&&c.usedTemperatureGrid);printf("cell814 raw=%.17g allowanceJ=%.17g effective=%.17g\n",double(c.rawNormalized),double(c.allowedResidual),double(c.effectiveNormalized));auto w=assessMaterialPublication(0.f,-5.714285362046212e-5f,1.f,3.814697265625e-6f);assert(w.accepted&&w.rawNormalized==1.f);printf("warmAbove raw=%.17g allowanceJ=%.17g effective=%.17g\n",double(w.rawNormalized),double(w.allowedResidual),double(w.effectiveNormalized));}
